import {HeadJson, toNumber} from 'shared';
import {DocRaw} from '../../types/doc-raw';
import {DocumentError} from '../../errors/document-error';

// generated by claude. Comments added by me.
export function validateTaxRates(headRaw: DocRaw, headJson: HeadJson): void {
    const hasGlobalRate = headJson.OHTMWS !== undefined && toNumber(headJson.OHTMWS) !== 0;
    // check to see if a globalRate is set. If so we don't need to check the rest.
    if (hasGlobalRate) {
        return;
    }


    // Check ALC of head.
    headJson.HEAD_ALC.forEach((alc, i) => {
        // needs a rate.
        if (hasNoRate(alc.OZAMWS)) {
            const raw = headRaw.alcs[i];
            throw new DocumentError(raw.lineNr, raw.type, craftErrorMessage('OZAMWS'));
        }
    });

    // Check every POS
    headJson.POS.forEach((pos, i) => {
        // headRaw.pos[i] has to be set because POS is build from it. Disable eslint non-null assertion to prevent a never failing check.
        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        const rawPos = headRaw.pos![i];

        // needs a rate
        if (hasNoRate(pos.OPOMWS)) {
            throw new DocumentError(rawPos.lineNr, rawPos.type, craftErrorMessage('OPOMWS'));
        }
        // check every alc of pos.
        pos.POS_ALC.forEach((alc, j) => {
            // needs a rate.
            if (hasNoRate(alc.OZAMWS)) {
                const rawAlc = rawPos.alcs[j];
                throw new DocumentError(rawAlc.lineNr, rawAlc.type, craftErrorMessage('OZAMWS'));
            }
        });
    });
}

function hasNoRate(rate: string | undefined): boolean {
    return rate === undefined || toNumber(rate) === 0;
}

function craftErrorMessage(field: string): string {
    return `${field}: Steuersatz fehlt, obwohl der Beleg keinen globalen Steuersatz (OHTMWS) hat.`;
}